//! Bundled datasets (repo `data/*.json`, refreshed with `mise run sync-data`).

use crate::world::World;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::sync::OnceLock;

/// Measured metrics for one Hokkaido site (generated by scripts/compute_earth_metrics.py).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EarthSite {
    pub id: String,
    pub name: String,
    #[serde(default)]
    pub en: Option<String>,
    pub lat: f64,
    pub lon: f64,
    pub elev_m: Option<f64>,
    pub slope_mean_deg: f64,
    pub slope_p90_deg: Option<f64>,
    pub relief_m: Option<f64>,
    pub ndvi_min: Option<f64>,
    pub ndvi_median: Option<f64>,
    pub barren_frac: Option<f64>,
    pub landcover_center: Option<String>,
    pub lst_night_jan_k: Option<f64>,
    pub lst_day_aug_k: Option<f64>,
    pub precip_mm_yr: Option<f64>,
    pub t2m_min_jan_c: Option<f64>,
    pub t2m_max_aug_c: Option<f64>,
    pub lithology_ja: Option<String>,
    pub lithology_en: Option<String>,
    pub age_ja: Option<String>,
    pub age_en: Option<String>,
}

/// A Moon/Mars reference target.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Body {
    pub id: String,
    pub world: World,
    pub name: String,
    pub ja: String,
    pub lat: f64,
    pub lon: f64,
    pub kind: String,
    pub task: Vec<String>,
    pub tmin: f64,
    pub tmax: f64,
    pub slope_mean_deg: f64,
    pub oxides: String,
    #[serde(default)]
    pub approx: bool,
    pub src: String,
}

/// Representative composition, wt% [SiO2, FeO(T), TiO2, Al2O3, MgO, CaO].
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Oxide {
    pub label: String,
    pub v: [f64; 6],
    pub src: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Landing {
    pub name: String,
    pub year: u16,
    pub agency: String,
    pub lat: f64,
    pub lon: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Preset {
    pub id: String,
    pub name: String,
    pub lat: f64,
    pub lon: f64,
    pub z: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Missions {
    pub landings: BTreeMap<World, Vec<Landing>>,
    pub presets: BTreeMap<World, Vec<Preset>>,
}

// The generated JSON uses `lst_night_jan_K` etc.; normalise keys to snake_case lowercase.
fn lower_keys(v: serde_json::Value) -> serde_json::Value {
    match v {
        serde_json::Value::Object(m) => m
            .into_iter()
            .map(|(k, v)| (k.to_lowercase(), lower_keys(v)))
            .collect(),
        serde_json::Value::Array(a) => a.into_iter().map(lower_keys).collect(),
        x => x,
    }
}

pub fn earth_sites() -> &'static [EarthSite] {
    static D: OnceLock<Vec<EarthSite>> = OnceLock::new();
    D.get_or_init(|| {
        let raw: serde_json::Value =
            serde_json::from_str(include_str!("../../../data/earth-metrics.json"))
                .expect("earth-metrics.json");
        serde_json::from_value(lower_keys(raw)).expect("earth-metrics.json schema")
    })
}

pub fn bodies() -> &'static [Body] {
    static D: OnceLock<Vec<Body>> = OnceLock::new();
    D.get_or_init(|| {
        serde_json::from_str(include_str!("../../../data/bodies.json")).expect("bodies.json")
    })
}

pub fn oxides() -> &'static BTreeMap<String, Oxide> {
    static D: OnceLock<BTreeMap<String, Oxide>> = OnceLock::new();
    D.get_or_init(|| {
        serde_json::from_str(include_str!("../../../data/oxides.json")).expect("oxides.json")
    })
}

pub fn missions() -> &'static Missions {
    static D: OnceLock<Missions> = OnceLock::new();
    D.get_or_init(|| {
        serde_json::from_str(include_str!("../../../data/missions.json")).expect("missions.json")
    })
}

/// Map GSJ lithology text to an oxide class. Order matters (most specific first).
pub fn lithology_class(ja: Option<&str>) -> &'static str {
    let Some(ja) = ja else { return "sediment" };
    if ja.contains("玄武岩質安山岩") || ja.contains("安山岩・玄武岩") {
        "basaltic_andesite"
    } else if ja.contains("玄武岩") {
        "basalt"
    } else if ja.contains("デイサイト") || ja.contains("石英安山岩") {
        "dacite"
    } else if ja.contains("流紋岩") {
        "rhyolite"
    } else if ja.contains("安山岩") {
        "andesite"
    } else {
        "sediment"
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn datasets_parse() {
        assert!(earth_sites().len() >= 10);
        assert!(bodies().len() >= 5);
        for b in bodies() {
            assert!(
                oxides().contains_key(&b.oxides),
                "missing oxide class {}",
                b.oxides
            );
        }
        assert!(!missions().landings[&World::Mars].is_empty());
        assert!(earth_sites().iter().any(|e| e.lst_night_jan_k.is_some()));
    }

    #[test]
    fn lithology_order() {
        assert_eq!(
            lithology_class(Some("玄武岩質安山岩 溶岩")),
            "basaltic_andesite"
        );
        assert_eq!(lithology_class(Some("石英安山岩")), "dacite");
        assert_eq!(lithology_class(Some("安山岩")), "andesite");
        assert_eq!(lithology_class(None), "sediment");
    }
}
